mapper.update:
UPDATE lunaerp_finance_supplier_recon_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{now}
WHERE recon_id = #{reconId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_supplier_recon_item
WHERE recon_id = #{reconId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
